BEGIN;
ON CONFLICT (series_code, year) DO UPDATE SET starts_at=EXCLUDED.starts_at, ends_at=EXCLUDED.ends_at;
ON CONFLICT (participant_id) DO UPDATE SET legal_name=EXCLUDED.legal_name,business_type=EXCLUDED.business_type,scale_class=EXCLUDED.scale_class,data_origin='SYNTHETIC';
ON CONFLICT (participant_id,series_code,compliance_period) DO UPDATE SET allocated_quota=EXCLUDED.allocated_quota,verified_emission=EXCLUDED.verified_emission,eligible_banked_units=EXCLUDED.eligible_banked_units,eligible_offset_applied=EXCLUDED.eligible_offset_applied,source_status=EXCLUDED.source_status,source_reference=EXCLUDED.source_reference,data_origin='SYNTHETIC',import_batch_id=EXCLUDED.import_batch_id,version=annual_compliance_positions.version+1,updated_at=now()
WHERE (annual_compliance_positions.allocated_quota,annual_compliance_positions.verified_emission,annual_compliance_positions.eligible_banked_units,annual_compliance_positions.eligible_offset_applied,annual_compliance_positions.source_status,annual_compliance_positions.source_reference,annual_compliance_positions.data_origin,annual_compliance_positions.import_batch_id) IS DISTINCT FROM (EXCLUDED.allocated_quota,EXCLUDED.verified_emission,EXCLUDED.eligible_banked_units,EXCLUDED.eligible_offset_applied,EXCLUDED.source_status,EXCLUDED.source_reference,EXCLUDED.data_origin,EXCLUDED.import_batch_id);
ON CONFLICT (participant_id,series_code,compliance_period) DO NOTHING;
COMMIT;
